import { test, expect } from '@playwright/test';

test.describe('Horizontal Scrolling Disabled on Main Layout', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/main-layout');
  });

  test('should disable horizontal scrolling when viewport is mobile size', async ({ page }) => {
    // Set viewport to mobile size
    await page.setViewportSize({ width: 375, height: 667 });

    // Verify main content is visible without horizontal scrollbar
    const mainContent = page.getByRole('main');
    await expect(mainContent).toBeVisible();

    // Verify no horizontal scrollbar is present
    const scrollbar = page.locator('[data-testid="horizontal-scrollbar"]');
    await expect(scrollbar).not.toBeVisible();

    // Verify content fits within viewport width
    const contentWidth = await mainContent.evaluate((el) => el.scrollWidth);
    const viewportWidth = 375;
    expect(contentWidth).toBeLessThanOrEqual(viewportWidth);

    // Verify user can scroll vertically
    const verticalScroll = page.locator('[data-testid="vertical-scrollbar"]');
    await expect(verticalScroll).toBeVisible();
    await verticalScroll.evaluate((el) => el.scrollTop = 100);
    await expect(mainContent).toHaveScrollTop(100);
  });

  test('should allow horizontal scrolling when viewport is desktop size', async ({ page }) => {
    // Set viewport to desktop size
    await page.setViewportSize({ width: 1920, height: 1080 });

    // Verify main content is visible
    const mainContent = page.getByRole('main');
    await expect(mainContent).toBeVisible();

    // Verify horizontal scrollbar is present
    const scrollbar = page.locator('[data-testid="horizontal-scrollbar"]');
    await expect(scrollbar).toBeVisible();

    // Verify content overflows viewport width
    const contentWidth = await mainContent.evaluate((el) => el.scrollWidth);
    const viewportWidth = 1920;
    expect(contentWidth).toBeGreaterThan(viewportWidth);

    // Verify user can scroll horizontally
    const horizontalScroll = page.locator('[data-testid="horizontal-scrollbar"]');
    await horizontalScroll.evaluate((el) => el.scrollLeft = 500);
    await expect(mainContent).toHaveScrollLeft(500);

    // Verify user can scroll vertically
    const verticalScroll = page.locator('[data-testid="vertical-scrollbar"]');
    await verticalScroll.evaluate((el) => el.scrollTop = 100);
    await expect(mainContent).toHaveScrollTop(100);
  });
});
